#!/usr/bin/env python3
"""
Imports darwinkit, Harold Brenes' Objective-C framework bindings for macOS and iOS
(https://github.com/harold-b/darwodin), into `core:sys/darwin` and `vendor:darwin`.

darwinkit is generated from the macOS and iOS SDK headers by csgen and merged into a
single tree with `#+build darwin:default` / `#+build darwin:ios` tags. Regenerating it
needs a Mac with Xcode; this script only post-processes the result so it can live in
the Odin repository:

  - each framework is placed in `core:sys/darwin` or `vendor:darwin` (see CORE_FRAMEWORKS)
  - relative imports ("../Foundation") become collection imports
  - darwodin's own `libc` and `mach` packages are replaced by `core:sys/posix` and `core:sys/darwin`
  - overload groups made only of class methods get `objc_is_class_method=true`
  - methods taking a trailing `^^NS.Error` out-parameter get an Odin-style wrapper which
    returns `(res: T, err: ^NS.Error)` (or `(ok: bool, err: ^NS.Error)`); the raw method
    is kept with an `_error` suffix
  - a few known problems in the generated output are patched (see KNOWN_FIXES)

Every generated file starts with GENERATED_MARKER. Only files carrying that marker are
overwritten or deleted, so hand-written files (e.g. `Foundation_extras.odin`) placed next
to them are never touched.

Usage:
	python vendor/darwin/_gen/import_darwinkit.py <path/to/darwodin/darwinkit> [--dry-run] [--verbose]
"""

import argparse
import os
import re
import sys
from collections import defaultdict


