RE_IMPORT        = re.compile(r'^import\s+(\w+)\s+"([^"]+)"\s*$')
RE_METHOD_ATTR   = re.compile(r'^(\s*)@\(objc_type=(\w+), objc_selector="([^"]+)", objc_name="(\w+)"(, objc_is_class_method=true)?\)\s*$')
RE_PROC_DECL     = re.compile(r'^(\s*)(\w+) :: proc\(')
RE_GROUP_ATTR    = re.compile(r'^(\s*)@\(objc_type=(\w+), objc_name="(\w+)"(, objc_is_class_method=true)?\)\s*$')
RE_GROUP_DECL    = re.compile(r'^(\s*)(\w+) :: proc \{\s*$')
RE_GROUP_MEMBER  = re.compile(r'^(\s*)(\w+),\s*$')
RE_GROUP_END     = re.compile(r'^\s*\}\s*$')
RE_WHEN          = re.compile(r'^\s*when (.+) \{\s*$')
RE_DECL_NAME     = re.compile(r'^\s*(\w+)\s*::')
RE_ERROR_OUT     = re.compile(r'^\^(\^(?:\w+\.)?Error)$')


class Method:
	def __init__(self, file, attr_idx, decl_idx, objc_type, selector, objc_name, is_class, name, params, ret, conds):
		self.file      = file
		self.attr_idx  = attr_idx
		self.decl_idx  = decl_idx
		self.objc_type = objc_type
		self.selector  = selector
		self.objc_name = objc_name
		self.is_class  = is_class
		self.name      = name
		self.params    = params # [(name, type)]
		self.ret       = ret    # str or None
		self.conds     = conds  # enclosing `when` conditions

	def odin_params(self):
		# parameters as seen at the call site, i.e. without `self`
		return self.params if self.is_class else self.params[1:]


class Group:
	def __init__(self, file, attr_idx, decl_idx, end_idx, objc_type, objc_name, is_class, name, members):
		self.file      = file
		self.attr_idx  = attr_idx
		self.decl_idx  = decl_idx
		self.end_idx   = end_idx
		self.objc_type = objc_type
		self.objc_name = objc_name
		self.is_class  = is_class
		self.name      = name
		self.members   = members


class Wrapper:
	def __init__(self, raw, name, objc_name, raw_name, raw_objc_name, err_type):
		self.raw           = raw
		self.name          = name
		self.objc_name     = objc_name
		self.raw_name      = raw_name
		self.raw_objc_name = raw_objc_name
		self.err_type      = err_type


def split_top_level(s, sep=","):
	parts, depth, cur, in_str = [], 0, [], False
	for ch in s:
		if ch == '"':
			in_str = not in_str
		elif not in_str:
			if ch in "([{":
				depth += 1
			elif ch in ")]}":
				depth -= 1
			elif ch == sep and depth == 0:
				parts.append("".join(cur).strip())
				cur = []
				continue
		cur.append(ch)
	if "".join(cur).strip():
		parts.append("".join(cur).strip())
	return parts


def parse_proc_signature(line):
	"""Parses `Name :: proc(params) -> ret ---`, returning (params, ret) or None."""
	m = RE_PROC_DECL.match(line)
	if not m:
		return None
	start = m.end()
	depth = 1
	i = start
	while i < len(line) and depth > 0:
		if line[i] == "(":
			depth += 1
		elif line[i] == ")":
			depth -= 1
		i += 1
	if depth != 0:
		return None
	params_str = line[start:i-1]
	rest = line[i:].strip()
	if not rest.endswith("---"):
		return None
	rest = rest[:-3].strip()
	ret = None
	if rest.startswith("->"):
		ret = rest[2:].strip()
	elif rest:
		return None

	params = []
	for p in split_top_level(params_str):
		name, _, ty = p.partition(":")
		params.append((name.strip(), ty.strip()))
	return params, ret


def brace_delta(line):
	delta, in_str = 0, False
	for i, ch in enumerate(line):
		if ch == '"' and (i == 0 or line[i-1] != "\\"):
			in_str = not in_str
		elif not in_str:
			if ch == "/" and line[i:i+2] == "//":
				break
			if ch == "{":
				delta += 1
			elif ch == "}":
				delta -= 1
	return delta


class Package:
	def __init__(self, name, files):
		self.name     = name
		self.files    = files # filename -> [lines]
		self.methods  = []
		self.groups   = []
		self.wrappers = []
		self.report   = defaultdict(list)

	def scan(self):
		self.methods = []
		self.groups  = []
		for fname, lines in self.files.items():
			when_stack = [] # [(depth at open, cond)]
			depth = 0
			i = 0
			while i < len(lines):
				line = lines[i]
				conds = tuple(c for _, c in when_stack)

				m = RE_METHOD_ATTR.match(line)
				if m and i+1 < len(lines):
					sig = parse_proc_signature(lines[i+1])
					d = RE_PROC_DECL.match(lines[i+1])
					if sig and d:
						params, ret = sig
						self.methods.append(Method(fname, i, i+1, m.group(2), m.group(3), m.group(4), bool(m.group(5)), d.group(2), params, ret, conds))

				m = RE_GROUP_ATTR.match(line)
				if m and i+1 < len(lines) and RE_GROUP_DECL.match(lines[i+1]):
					d = RE_GROUP_DECL.match(lines[i+1])
					members = []
					j = i+2
					while j < len(lines) and not RE_GROUP_END.match(lines[j]):
						mm = RE_GROUP_MEMBER.match(lines[j])
						if mm:
							members.append(mm.group(2))
						j += 1
					self.groups.append(Group(fname, i, i+1, j, m.group(2), m.group(3), bool(m.group(4)), d.group(2), members))

				w = RE_WHEN.match(line)
				if w:
					when_stack.append((depth, w.group(1)))
					depth += 1
				else:
					depth += brace_delta(line)
					while when_stack and when_stack[-1][0] >= depth:
						when_stack.pop()
				i += 1

	def all_decl_names(self):
		names = set()
		for lines in self.files.values():
			for line in lines:
				m = RE_DECL_NAME.match(line)
				if m:
					names.add(m.group(1))
		return names


def rewrite_imports(pkg, framework_of_path):
	for fname, lines in pkg.files.items():
		needed = {}
		removed = set()
		out = []
		for line in lines:
			m = RE_IMPORT.match(line)
			if m:
				alias, path = m.group(1), m.group(2)
				if path in ("../../libc", "../../mach"):
					removed.add(alias)
					continue # replaced below
				if path.startswith("../"):
					target = path[3:]
					if target not in framework_of_path:
						raise SystemExit(f"{pkg.name}/{fname}: unknown import {path!r}")
					if pkg.name in CORE_FRAMEWORKS and target not in CORE_FRAMEWORKS:
						raise SystemExit(f"{pkg.name}/{fname}: core package imports vendor package {target!r}")
					line = f'import {alias} "{framework_of_path[target]}"'
			out.append(line)

		def sub(table, prefix):
			def repl(m):
				sym = m.group(1)
				if sym not in table:
					raise SystemExit(f"{pkg.name}/{fname}: no mapping for {prefix}.{sym}")
				alias, name = table[sym]
				needed[alias] = REPLACEMENT_IMPORTS[alias]
				return f"{alias}.{name}"
			return repl

		text = "\n".join(out)
		if "mach" in removed:
			text = re.sub(r"(?<![\w.])mach\.(\w+)", sub(MACH_MAP, "mach"), text)
		if "libc" in removed:
			text = re.sub(r"(?<![\w.])libc\.(\w+)", sub(LIBC_MAP, "libc"), text)
		out = text.split("\n")

		if needed:
			existing = {RE_IMPORT.match(l).group(1) for l in out if RE_IMPORT.match(l)}
			new_lines = [f'import {a} "{p}"' for a, p in sorted(needed.items()) if a not in existing]
			# insert after the last import, or after the package line
			at = None
			for k, l in enumerate(out):
				if RE_IMPORT.match(l):
					at = k+1
			if at is None:
				at = next(k for k, l in enumerate(out) if l.startswith("package "))+1
				new_lines = [""] + new_lines
			out[at:at] = new_lines
		pkg.files[fname] = out


def plan_error_wrappers(pkg):
	names = pkg.all_decl_names()
	objc_names = defaultdict(set) # (type, is_class) -> names
	for m in pkg.methods:
		objc_names[(m.objc_type, m.is_class)].add(m.objc_name)
	for g in pkg.groups:
		objc_names[(g.objc_type, g.is_class)].add(g.objc_name)

	for m in pkg.methods:
		if not m.params:
			continue
		em = RE_ERROR_OUT.match(m.params[-1][1])
		if not em:
			continue
		ns = objc_names[(m.objc_type, m.is_class)]
		prefix = m.name[:len(m.name)-len(m.objc_name)]
		if not m.name.endswith(m.objc_name):
			pkg.report["skipped (unexpected naming)"].append(m.name)
			continue

		if m.objc_name.endswith("_error"):
			raw_objc = m.objc_name
			objc = m.objc_name[:-len("_error")]
			if objc in ns or prefix+objc in names:
				objc += "_"
			if objc in ns or prefix+objc in names:
				pkg.report["skipped (name taken)"].append(m.name)
				continue
		else:
			objc = m.objc_name
			raw_objc = m.objc_name + "_error"
			if raw_objc in ns or prefix+raw_objc in names:
				pkg.report["skipped (raw name taken)"].append(m.name)
				continue

		w = Wrapper(m, prefix+objc, objc, prefix+raw_objc, raw_objc, em.group(1))
		names.add(w.name)
		names.add(w.raw_name)
		ns.add(objc)
		ns.add(raw_objc)
		pkg.wrappers.append(w)


def apply_error_wrappers(pkg):
	by_name = {m.name: m for m in pkg.methods}

	# rename raw methods which did not already end in `_error`
	for w in pkg.wrappers:
		m = w.raw
		if m.name == w.raw_name:
			continue
		lines = pkg.files[m.file]
		lines[m.attr_idx] = lines[m.attr_idx].replace(f'objc_name="{m.objc_name}"', f'objc_name="{w.raw_objc_name}"')
		lines[m.decl_idx] = re.sub(rf"^(\s*){re.escape(m.name)} ::", rf"\g<1>{w.raw_name} ::", lines[m.decl_idx])

	# update overload groups to refer to the wrappers
	wrapper_by_old_name = {w.raw.name: w for w in pkg.wrappers}

	def effective_sig(name):
		w = wrapper_by_old_name.get(name)
		if w:
			return [t for _, t in w.raw.odin_params()[:-1]]
		m = by_name.get(name)
		return [t for _, t in m.odin_params()] if m else None

	for g in pkg.groups:
		lines = pkg.files[g.file]
		renames = {}
		for member in g.members:
			w = wrapper_by_old_name.get(member)
			if not w:
				continue
			sig = effective_sig(member)
			if any(other != member and effective_sig(other) == sig for other in g.members):
				pkg.report["kept raw in group (signature clash)"].append(f"{g.name}: {w.raw_name}")
				renames[member] = w.raw_name
			else:
				renames[member] = w.name
		renames = {k: v for k, v in renames.items() if k != v}
		if not renames:
			continue
		for k in range(g.decl_idx+1, g.end_idx):
			mm = RE_GROUP_MEMBER.match(lines[k])
			if mm and mm.group(2) in renames:
				lines[k] = f"{mm.group(1)}{renames[mm.group(2)]},"
		g.members = [renames.get(n, n) for n in g.members]

	# emit the wrappers at the end of the file of their raw method, per `when` condition
	per_file = defaultdict(lambda: defaultdict(list))
	for w in pkg.wrappers:
		per_file[w.raw.file][w.raw.conds].append(w)

	for fname, by_cond in per_file.items():
		lines = pkg.files[fname]
		while lines and lines[-1].strip() == "":
			lines.pop()
		lines.append("")
		lines.append("")
		lines.append("// Odin-style wrappers for methods with a trailing `^^Error` out-parameter")
		for conds, ws in by_cond.items():
			indent = ""
			for c in conds:
				lines.append("")
				lines.append(f"{indent}when {c} {{")
				indent += "\t"
			for w in ws:
				lines.append("")
				lines.extend(indent+l if l else l for l in emit_wrapper(w))
			for _ in conds:
				indent = indent[:-1]
				lines.append(f"{indent}}}")
		lines.append("")


def emit_wrapper(w):
	m = w.raw
	params = m.params[:-1]
	taken = {n for n, _ in params}

	def fresh(name):
		while name in taken:
			name += "_"
		taken.add(name)
		return name

	err = fresh("err")
	if m.ret is None:
		results = f"({err}: {w.err_type})"
		res = None
	elif m.ret == "bool":
		res = fresh("ok")
		results = f"({res}: bool, {err}: {w.err_type})"
	else:
		res = fresh("res")
		ret = f"^{m.objc_type}" if m.ret == "instancetype" else m.ret
		results = f"({res}: {ret}, {err}: {w.err_type})"

	param_str = ", ".join(f"{n}: {t}" for n, t in params)
	args = [n for n, _ in params] + [f"&{err}"]
	if m.is_class:
		# NOTE: `Type.method()` rather than `Type_method()`, as the latter gives `Type` instead of `^Type` for `instancetype`
		call = f"{m.objc_type}.{w.raw_objc_name}({', '.join(args)})"
		attr = f'@(objc_type={m.objc_type}, objc_name="{w.objc_name}", objc_is_class_method=true)'
	else:
		call = f"{w.raw_name}({', '.join(args)})"
		attr = f'@(objc_type={m.objc_type}, objc_name="{w.objc_name}")'

	out = [attr, f'{w.name} :: #force_inline proc "c" ({param_str}) -> {results} {{']
	out.append(f"\t{res} = {call}" if res else f"\t{call}")
	out.append("\treturn")
	out.append("}")
	return out


def fix_class_method_groups(pkg):
	kinds = {m.name: m.is_class for m in pkg.methods}
	for w in pkg.wrappers:
		kinds[w.name]     = w.raw.is_class
		kinds[w.raw_name] = w.raw.is_class
	for g in pkg.groups:
		member_kinds = {kinds.get(n) for n in g.members}
		if None in member_kinds:
			pkg.report["groups with unknown members"].append(g.name)
			continue
		if member_kinds == {True} and not g.is_class:
			lines = pkg.files[g.file]
			lines[g.attr_idx] = lines[g.attr_idx].replace(f'objc_name="{g.objc_name}")', f'objc_name="{g.objc_name}", objc_is_class_method=true)')
			g.is_class = True
			pkg.report["class-method groups fixed"].append(g.name)
		elif len(member_kinds) > 1:
			pkg.report["mixed instance/class groups"].append(g.name)


def flag_element_name(name):
	if name in FLAG_ELEMENT_NAMES:
		return FLAG_ELEMENT_NAMES[name]
	if name.endswith("ies"):
		return name[:-3] + "y"
	if name.endswith("s") and not name.endswith(("ss", "us")): # e.g. not `Status`
		return name[:-1]
	return name + "Flag"


def apply_enum_member_fixes(pkg):
	wanted = dict(ENUM_MEMBER_FIXES.get(pkg.name, {}))
	if not wanted:
		return
	for fname, lines in pkg.files.items():
		k = 0
		while k < len(lines):
			m = re.match(r"^\s*(\w+) :: enum [\w.]+ \{\s*$", lines[k])
			if not m or m.group(1) not in wanted:
				k += 1
				continue
			name = m.group(1)
			prefix, renames = wanted.pop(name)

			j = k+1
			members = []
			while not re.match(r"^\s*\}", lines[j]):
				mm = re.match(r"^(\s*)(\w+)\s*=\s*(.*)$", lines[j])
				if not mm:
					raise SystemExit(f"{pkg.name}/{fname}: cannot parse member of enum {name}: {lines[j]!r}")
				members.append(mm.groups())
				j += 1

			fixed = []
			unused = set(renames)
			for indent, member, rest in members:
				new = member
				if member in renames:
					unused.discard(member)
					new = renames[member]
					if new is None:
						continue
				elif prefix and member.startswith(prefix) and len(member) > len(prefix):
					new = member[len(prefix):]
					if new[0].isdigit():
						new = "_" + new
				fixed.append((indent, new, rest))
			if unused:
				pkg.report["enum member fix no longer applies"].append(f"{name}: {', '.join(sorted(unused))}")
			new_names = [n for _, n, _ in fixed]
			if len(set(new_names)) != len(new_names):
				raise SystemExit(f"{pkg.name}/{fname}: fixing the members of {name} makes duplicate names")

			width = max(len(n) for n in new_names)
			lines[k+1:j] = [f"{indent}{n.ljust(width)} = {rest}" for indent, n, rest in fixed]
			pkg.report["enum members fixed"].append(f"{name}: {', '.join(new_names)}")
			k = j
	for name in sorted(wanted):
		pkg.report["enum for member fix not found"].append(name)


RE_ENUM_DECL   = re.compile(r"^(\s*)(\w+) :: enum ([\w.]+) \{\s*$")
RE_ENUM_MEMBER = re.compile(r"^(\s*)(\w+)\s*=\s*(.*)$")


def read_enum(lines, k):
	"""The members of the enum declared at `lines[k]`, as [(indent, name, value)], and the index of its `}`."""
	j = k+1
	members = []
	while not re.match(r"^\s*\}", lines[j]):
		mm = RE_ENUM_MEMBER.match(lines[j])
		if mm:
			members.append(mm.groups())
		j += 1
	return members, j


def unflag_enums(pkg):
	"""Turns the bit_sets in `NOT_FLAG_ENUMS` back into plain enums."""
	for set_name, dropped in NOT_FLAG_ENUMS.get(pkg.name, {}).items():
		set_at = None
		for fname, lines in pkg.files.items():
			for k, line in enumerate(lines):
				m = re.match(rf"^\s*{set_name} :: bit_set\[(\w+); ([\w.]+)\]\s*$", line)
				if m:
					set_at = (fname, k, m.group(1), m.group(2))
		if set_at is None:
			pkg.report["bit_set to turn back into an enum not found"].append(set_name)
			continue
		fname, set_k, elem, backing = set_at

		# element members are bit indices; the combination constants are sets of them
		values = dict(dropped)
		elem_at = None
		for f, lines in pkg.files.items():
			for k, line in enumerate(lines):
				m = RE_ENUM_DECL.match(line)
				if m and m.group(2) == elem:
					elem_at = (f, k)
					members, _ = read_enum(lines, k)
					for _, name, value in members:
						values[name] = 1 << int(value.rstrip(",").strip())
		consts = []
		for f, lines in pkg.files.items():
			for k, line in enumerate(lines):
				m = re.match(rf"^\s*{set_name}_(\w+) :: {set_name} \{{(.*)\}}\s*$", line)
				if m:
					bits = [b.strip().lstrip(".") for b in m.group(2).split(",") if b.strip()]
					value = 0
					for b in bits:
						value |= values[b]
					values[m.group(1)] = value
					consts.append((f, k))
		if elem_at is None:
			raise SystemExit(f"{pkg.name}: element enum {elem} of {set_name} not found")

		# remove the bit_set and its constants, last line first
		for rf, rk in sorted([(fname, set_k)] + consts, key=lambda x: (x[0], -x[1])):
			rl = pkg.files[rf]
			del rl[rk]
			if 0 < rk < len(rl) and not rl[rk].strip() and not rl[rk-1].strip():
				del rl[rk]

		lines = pkg.files[elem_at[0]]
		k = next(k for k, line in enumerate(lines) if RE_ENUM_DECL.match(line) and RE_ENUM_DECL.match(line).group(2) == elem)
		indent = RE_ENUM_DECL.match(lines[k]).group(1)
		_, end = read_enum(lines, k)
		ordered = sorted(values.items(), key=lambda x: (x[1], x[0]))
		width = max(len(n) for n, _ in ordered)
		lines[k:end+1] = [f"{indent}{elem} :: enum {backing} {{"] + [f"{indent}\t{n.ljust(width)} = {v}," for n, v in ordered] + [f"{indent}}}"]
		for f2, lines2 in pkg.files.items():
			for i, line in enumerate(lines2):
				if re.search(rf"\b{set_name}\b", line):
					lines2[i] = re.sub(rf"\b{set_name}\b", elem, line)
					pkg.report["bit_set references changed to the enum"].append(f"{f2}: {lines2[i].strip()}")
		pkg.report["bit_sets turned back into enums"].append(f"{set_name} -> {elem}: " + ", ".join(f"{n} = {v}" for n, v in ordered))


def c_prefix_word_start(name, n):
	return len(name) > n and (name[n].isupper() or name[n].isdigit() or name[n] == "_")


def c_prefix_finish(rest):
	rest = rest.lstrip("_")
	return "_" + rest if rest[0].isdigit() else rest


def c_prefix_length(enum_name, members):
	"""How much of each member is the C prefix: `kSecPaddingNone` in `SecPadding` -> len("kSecPadding")."""
	if len(members) == 1:
		body = members[0][1:]
		key = enum_name[:-1] if enum_name.endswith("s") else enum_name
		# the enum's name anywhere after a framework prefix: `kAudioFileStreamParseFlag_Discontinuity`
		at = body.find(key)
		if at >= 0 and (at == 0 or body[at].isupper()):
			n = at + len(key)
			if body[n:n+1] == "s":
				n += 1
			if c_prefix_word_start(body, n):
				return 1 + n
		# the enum's first words: `kSecItemPemArmour` in `SecItemImportExportFlags`
		n = len(os.path.commonprefix([body, enum_name]))
		while n > 0 and not (c_prefix_word_start(body, n) and c_prefix_word_start(enum_name, n)):
			n -= 1
		return 1 + n
	p = os.path.commonprefix(members)
	n = len(p)
	while n > 1 and not all(c_prefix_word_start(m, n) for m in members):
		n -= 1
	# don't strip past the enum's own name: `kEAGLRenderingAPIOpenGLES1` -> `OpenGLES1`
	for cand in (enum_name + "s_", enum_name + "_", enum_name + "s", enum_name):
		at = p[:n].find(cand)
		if at > 0:
			cut = at + len(cand)
			if cut < n and all(c_prefix_word_start(m, cut) for m in members):
				n = cut
			break
	return max(n, 1)


def strip_c_member_prefixes(pkg):
	"""
	csgen strips the type's prefix from enum members, but not a C-style `k` prefix:
	`kSecPaddingNone` becomes `None`, `kCGLPFADoubleBuffer` becomes `DoubleBuffer`.
	"""
	renames = {}   # old member -> new member, for references such as `.kCMTimeFlags_Valid`
	prefixes = {}  # enum -> length of its members' prefix, for csgen's combination constants
	for fname, lines in pkg.files.items():
		for k, line in enumerate(lines):
			m = RE_ENUM_DECL.match(line)
			if not m or m.group(2).islower():
				continue
			members, end = read_enum(lines, k)
			names = [n for _, n, _ in members]
			if not names or not all(re.match(r"k[A-Z0-9]", n) for n in names):
				continue
			n = c_prefix_length(m.group(2), names)
			new_names = [c_prefix_finish(x[n:]) for x in names]
			if len(set(new_names)) != len(new_names):
				pkg.report["C prefixes kept (names would clash)"].append(m.group(2))
				continue
			width = max(len(x) for x in new_names)
			lines[k+1:end] = [f"{indent}{new.ljust(width)} = {value}" for (indent, _, value), new in zip(members, new_names)]
			renames.update(zip(names, new_names))
			prefixes[m.group(2)] = n
			pkg.report["C prefixes stripped from enum members"].append(f"{m.group(2)}: {names[0][:n]}")
	if not renames:
		return

	# csgen's combination constants of bit_sets: `TimeFlags_kCMTimeFlags_ImpliedValueFlagsMask`
	elem_of = {}
	for lines in pkg.files.values():
		for line in lines:
			m = re.match(r"^\s*(\w+) :: bit_set\[(\w+);", line)
			if m:
				elem_of[m.group(1)] = m.group(2)
	const_renames = {}
	for lines in pkg.files.values():
		for line in lines:
			m = re.match(r"^\s*((\w+?)_(k[A-Z0-9]\w*)) ::", line)
			if m and m.group(2) in elem_of and elem_of[m.group(2)] in prefixes:
				n = prefixes[elem_of[m.group(2)]]
				if c_prefix_word_start(m.group(3), n):
					const_renames[m.group(1)] = f"{m.group(2)}_{c_prefix_finish(m.group(3)[n:])}"

	member_ref = re.compile(r"\.(k[A-Z0-9]\w*)\b")
	const_ref = re.compile(r"\b(" + "|".join(map(re.escape, sorted(const_renames, key=len, reverse=True))) + r")\b") if const_renames else None
	for lines in pkg.files.values():
		for i, line in enumerate(lines):
			new = member_ref.sub(lambda mm: "." + renames.get(mm.group(1), mm.group(1)), line)
			if const_ref:
				new = const_ref.sub(lambda mm: const_renames[mm.group(1)], new)
			lines[i] = new
	for a, b in const_renames.items():
		pkg.report["bit_set constants renamed"].append(f"{a} -> {b}")


def apply_flag_enums(pkg):
	field_bits = FLAG_ENUM_FIELDS.get(pkg.name, {})
	wanted = set(FLAG_ENUMS.get(pkg.name, [])) | set(field_bits)
	if not wanted:
		return
	names = pkg.all_decl_names()
	elem_of = {} # an enum may be declared once per platform in separate `when` blocks
	for fname, lines in pkg.files.items():
		k = 0
		while k < len(lines):
			m = re.match(r"^(\s*)(\w+) :: enum ([\w.]+) \{\s*$", lines[k])
			if not m or m.group(2) not in wanted:
				k += 1
				continue
			indent, name, backing = m.group(1), m.group(2), m.group(3)

			members = []
			j = k+1
			while lines[j].strip() != "}":
				mm = re.match(r"^\s*(\w+)\s*=\s*(-?\w+),\s*$", lines[j])
				if not mm:
					raise SystemExit(f"{pkg.name}/{fname}: cannot parse member of flag enum {name}: {lines[j]!r}")
				members.append((mm.group(1), int(mm.group(2), 0)))
				j += 1

			first = name not in elem_of
			if first:
				elem = flag_element_name(name)
				if elem in names:
					elem = name + "Flag"
				if elem in names:
					raise SystemExit(f"{pkg.name}/{fname}: no free element name for flag enum {name}")
				names.add(elem)
				elem_of[name] = elem
			elem = elem_of[name]

			fields    = field_bits.get(name, 0)
			is_flag   = lambda v: v > 0 and v & (v-1) == 0 and not v & fields
			flags     = [(n, v) for n, v in members if is_flag(v)]
			constants = [(n, v) for n, v in members if not is_flag(v)]
			named_bits = 0
			for _, v in flags:
				named_bits |= v
			if fields:
				# every bit of a field, or of a constant, gets an element `_Bit<n>`, so that the constants
				# lie within the bit_set and `opts & ~Mask` clears the same bits as `opts &~ Mask`
				used = fields
				for n, v in constants:
					if v < 0:
						raise SystemExit(f"{pkg.name}/{fname}: negative member {n} of flag enum {name}")
					used |= v
				extra = used & ~named_bits
				bit_names = [(f"_Bit{i}", 1 << i) for i in range(extra.bit_length()) if extra >> i & 1]
				for n, _ in bit_names:
					if any(n == fn for fn, _ in flags):
						raise SystemExit(f"{pkg.name}/{fname}: flag enum {name} already has a member {n}")
				flags += bit_names
				named_bits |= extra
			width = max((len(n) for n, _ in flags), default=0)
			out = [f"{elem} :: enum {backing} {{"]
			out += [f"\t{n.ljust(width)} = {v.bit_length()-1}," for n, v in flags]
			out += ["}", f"{name} :: bit_set[{elem}; {backing}]"]
			for n, v in constants:
				const_name = f"{name}_{n}"
				if first and const_name in names:
					raise SystemExit(f"{pkg.name}/{fname}: constant {const_name} for flag enum {name} is already declared")
				names.add(const_name)
				if v & ~named_bits:
					# sets bits which no member names, e.g. `All = 0xffffffff`
					out.append(f"{const_name} :: transmute({name}){backing}({hex(v)})")
					continue
				bits, seen = [], 0
				for fn, fv in flags:
					if v & fv and not seen & fv: # one name per bit, skipping aliases
						bits.append(f".{fn}")
						seen |= fv
				out.append(f"{const_name} :: {name}{{{', '.join(bits)}}}")
			out = [indent + l for l in out]
			lines[k:j+1] = out
			consts = ", ".join(f"{name}_{n}" for n, _ in constants)
			pkg.report["flag enums converted"].append(f"{name} -> bit_set[{elem}]" + (f" (constants {consts})" if consts else ""))
			k += len(out)
	for name in sorted(wanted - set(elem_of)):
		pkg.report["flag enum not found"].append(name)


def apply_alias_fixes(pkg):
	if pkg.name not in ALIAS_FIXES:
		return
	alias, path, table = ALIAS_FIXES[pkg.name]
	found = set()
	for fname, lines in pkg.files.items():
		changed = False
		for k, line in enumerate(lines):
			m = re.match(r"^(\w+)(\s*::\s*)(.+?)\s*$", line)
			if m and m.group(1) in table:
				lines[k] = f"{m.group(1)}{m.group(2)}{table[m.group(1)]}"
				found.add(m.group(1))
				changed = True
		if changed:
			last = max(k for k, l in enumerate(lines) if RE_IMPORT.match(l))
			lines.insert(last+1, f'import {alias} "{path}"')
	for name in sorted(set(table) - found):
		pkg.report["alias fix no longer applies"].append(name)
	for name in sorted(found):
		pkg.report["alias fixes applied"].append(f"{name} :: {table[name]}")


def find_handwritten_procs(dest):
	names = set()
	if os.path.isdir(dest):
		for f in sorted(os.listdir(dest)):
			p = os.path.join(dest, f)
			if f.endswith(".odin") and not is_generated(p):
				for line in read_lines(p):
					m = re.match(r"^(\w+)\s*::\s*(?:#force_inline\s+)?proc\b", line)
					if m:
						names.add(m.group(1))
	return names


def apply_extra_overloads(pkg, handwritten):
	targets = defaultdict(list)
	for n in sorted(handwritten):
		for suffix in OVERLOAD_SUFFIXES:
			if n.endswith(suffix):
				targets[n[:-len(suffix)]].append(n)
	if not targets:
		return

	pkg.scan()
	groups  = {g.name: g for g in pkg.groups}
	methods = {m.name: m for m in pkg.methods}
	names   = pkg.all_decl_names() | handwritten
	objc_names = defaultdict(set)
	for m in pkg.methods:
		objc_names[(m.objc_type, m.is_class)].add(m.objc_name)

	insertions = defaultdict(list)                    # file -> [(line index, lines)]
	appends    = defaultdict(lambda: defaultdict(list)) # file -> conds -> [lines]
	renamed    = {}
	for target, members in sorted(targets.items()):
		if target in groups:
			g = groups[target]
			lines = pkg.files[g.file]
			indent = RE_GROUP_MEMBER.match(lines[g.decl_idx+1]).group(1)
			insertions[g.file].append((g.end_idx, [f"{indent}{n}," for n in members]))
			pkg.report["hand-written overloads added to groups"].append(f"{target}: {', '.join(members)}")
		elif target in methods:
			m = methods[target]
			raw, raw_objc = target + "_", m.objc_name + "_"
			if raw in names or raw_objc in objc_names[(m.objc_type, m.is_class)]:
				pkg.report["hand-written overloads skipped (name taken)"].append(target)
				continue
			lines = pkg.files[m.file]
			lines[m.attr_idx] = lines[m.attr_idx].replace(f'objc_name="{m.objc_name}"', f'objc_name="{raw_objc}"')
			lines[m.decl_idx] = re.sub(rf"^(\s*){re.escape(m.name)} ::", rf"\g<1>{raw} ::", lines[m.decl_idx])
			renamed[target] = raw
			class_attr = ", objc_is_class_method=true" if m.is_class else ""
			appends[m.file][m.conds].append(
				[f'@(objc_type={m.objc_type}, objc_name="{m.objc_name}"{class_attr})', f"{target} :: proc {{", f"\t{raw},"] +
				[f"\t{n}," for n in members] + ["}"])
			pkg.report["methods made into groups with hand-written overloads"].append(f"{target}: {', '.join(members)}")
		else:
			pkg.report["hand-written overload target not found"].append(target)

	# other groups which referred to a renamed method
	for g in pkg.groups:
		lines = pkg.files[g.file]
		for k in range(g.decl_idx+1, g.end_idx):
			mm = RE_GROUP_MEMBER.match(lines[k])
			if mm and mm.group(2) in renamed:
				lines[k] = f"{mm.group(1)}{renamed[mm.group(2)]},"

	for fname, by_cond in appends.items():
		lines = pkg.files[fname]
		while lines and lines[-1].strip() == "":
			lines.pop()
		lines += ["", "", "// Overload groups which include hand-written overloads"]
		for conds, decls in by_cond.items():
			indent = ""
			for c in conds:
				lines += ["", f"{indent}when {c} {{"]
				indent += "\t"
			for decl in decls:
				lines.append("")
				lines.extend(indent+l for l in decl)
			for _ in conds:
				indent = indent[:-1]
				lines.append(f"{indent}}}")
		lines.append("")

	for fname, items in insertions.items():
		lines = pkg.files[fname]
		for at, new_lines in sorted(items, key=lambda x: -x[0]):
			lines[at:at] = new_lines


def reexport_foundation_extras(pkg, foundation_dest):
	"""
	csgen's `Foundation.Exports.odin` (in AppKit) re-exports every generated Foundation declaration, so that
	`import NS "vendor:darwin/AppKit"` gives all of `NS`, as `#import <AppKit/AppKit.h>` does in Objective-C.
	Add the hand-written top-level declarations of Foundation to it as well.
	"""
	exports = "Foundation.Exports.odin"
	if exports not in pkg.files or not os.path.isdir(foundation_dest):
		return
	names = pkg.all_decl_names()
	added, skipped = [], []
	for f in sorted(os.listdir(foundation_dest)):
		p = os.path.join(foundation_dest, f)
		if not f.endswith(".odin") or is_generated(p):
			continue
		lines = read_lines(p)
		for i, line in enumerate(lines):
			m = re.match(r"^(\w+)\s*::", line)
			if not m:
				continue
			prev = lines[i-1] if i else ""
			if prev.startswith("@(") and ("private" in prev or "objc_type" in prev):
				continue # private, or a method which is reached through its (aliased) type
			name = m.group(1)
			if name in names:
				skipped.append(name)
			elif name not in added:
				added.append(name)

	if added:
		lines = pkg.files[exports]
		while lines and lines[-1].strip() == "":
			lines.pop()
		width = max(len(n) for n in added)
		lines += ["", "", "// Hand-written declarations of core:sys/darwin/Foundation"]
		lines += [f"{n.ljust(width)} :: NS.{n}" for n in added]
		lines.append("")
	pkg.report["Foundation extras re-exported"].extend(added)
	pkg.report["Foundation extras not re-exported (name taken)"].extend(skipped)


def group_split_prefix(name):
	for p in GROUP_CLASS_PREFIXES:
		if name.startswith(p) and len(name) > len(p) and name[len(p)].isupper():
			return p, name[len(p):]
	return "", name


def group_stem(name):
	"""`NSMutableArray` -> `NSArray`, `MTLRenderPipelineColorAttachmentDescriptorArray` -> `MTLRenderPipelineColorAttachment`"""
	p, rest = group_split_prefix(name)
	if rest.startswith("Mutable") and len(rest) > 7 and rest[7].isupper():
		rest = rest[7:]
	changed = True
	while changed:
		changed = False
		for s in GROUP_ROLE_SUFFIXES:
			if rest.endswith(s) and len(rest) > len(s):
				rest = rest[:-len(s)]
				changed = True
	return p + rest


def group_words(rest):
	return re.findall(r"OpenGL|[A-Z0-9]+(?![a-z])|[A-Z][a-z0-9]*", rest)


def group_plural(word):
	if re.search(r"[^aeiou]y$", word):
		return word[:-1] + "ies"
	if re.search(r"(s|x|ch|sh)$", word):
		return word + "es"
	return word + "s"


def plan_groups(lines_of, super_of, parents_of):
	"""
	lines_of:   type -> line count
	super_of:   type -> superclass within the package
	parents_of: type -> superclass and protocols within the package
	Returns {file name: [types]}, without regard to build tags.
	"""
	stems = defaultdict(list)
	for n in sorted(lines_of):
		stems[group_stem(n)].append(n)
	stem_of = {n: s for s, ns in stems.items() for n in ns}
	names = sorted(stems, key=lambda s: (len(s), s))

	def inherits(s, t):
		return any(parents_of.get(n, set()) & set(stems[t]) for n in stems[s])

	# families: a tree of stems
	parent = {}
	for s in names:
		best = None
		# `MTLRenderPipelineState` -> `MTLRenderPipeline`
		for t in names:
			if t != s and s.startswith(t) and s[len(t)].isupper() and (best is None or len(t) > len(best)):
				best = t
		if best is None:
			# a subclass named after its superclass (`MTLRenderCommandEncoder` -> `MTLCommandEncoder`, `NSInputStream` -> `NSStream`)
			# or a descriptor variant (`MTLTileRenderPipelineDescriptor` -> `MTLRenderPipeline`)
			sp, srest = group_split_prefix(s)
			sw = group_words(srest)
			for t in names:
				tp, trest = group_split_prefix(t)
				tw = group_words(trest)
				if t == s or tp != sp or trest in GROUP_GENERIC_BASES:
					continue
				if not (len(sw) > len(tw) and sw[-len(tw):] == tw):
					continue
				if (inherits(s, t) or (len(tw) >= 2 and s not in stems[s])) and (best is None or len(t) > len(best)):
					best = t
		parent[s] = best
	children = defaultdict(list)
	for s in names:
		children[parent[s]].append(s)

	def collect(s):
		out = [s]
		for c in sorted(children[s]):
			out += collect(c)
		return out

	groups = {}
	family_of = {}
	singles = []
	for root in sorted(children[None]):
		members = [n for s in collect(root) for n in sorted(stems[s], key=lambda n: (len(n), n))]
		if len(members) == 1 and lines_of[members[0]] < GROUP_SINGLE_LINES:
			singles.append(members[0])
		else:
			groups[root] = members
			for n in members:
				family_of[n] = root

	# small single types go with their superclass (`NSDimension` with `NSUnit`)
	def home(n, seen=()):
		if n in family_of:
			return family_of[n]
		if n not in singles or lines_of[n] >= GROUP_SMALL_LINES or n in seen:
			return None
		p = super_of.get(n)
		if p is None or p in GROUP_ROOT_CLASSES or group_split_prefix(stem_of[p])[1] in GROUP_GENERIC_BASES:
			return None
		return home(p, seen + (n,)) or (p if p in singles else None)
	attached = {}
	for n in singles:
		h = home(n)
		if h:
			attached[n] = h
	singles = [n for n in singles if n not in attached]
	for n, h in attached.items():
		if h not in groups:
			if h in singles:
				singles.remove(h)
			groups[h] = [h]
		groups[h].append(n)

	# topics: families and single types sharing a first word, named after the words they all share
	def first_word(n):
		p, rest = group_split_prefix(group_stem(n))
		w = group_words(rest)
		return p + (w[0] if w else rest)
	topics = defaultdict(list)
	for g, ms in groups.items():
		topics[first_word(g)].append((g, ms))
	for n in singles:
		topics[first_word(n)].append((n, [n]))
	merged, leftover = {}, []
	for topic, entries in sorted(topics.items()):
		if len(entries) == 1:
			g, ms = entries[0]
			if g in groups:
				merged[g] = ms
			else:
				leftover.append(g)
			continue
		entries.sort(key=lambda e: (e[0] != topic, e[0]))
		members = [m for _, ms in entries for m in ms]
		p = group_split_prefix(topic)[0]
		common = None
		for m in members:
			w = group_words(group_split_prefix(group_stem(m))[1])
			if common is None:
				common = w
			else:
				i = 0
				while i < min(len(common), len(w)) and common[i] == w[i]:
					i += 1
				common = common[:i]
		merged.setdefault(p + "".join(common) if common else topic, []).extend(members)
	groups = merged

	# kinds: single types left on their own which share a last word (`NSClipView`, `NSRulerView`, ...)
	kinds = defaultdict(list)
	for n in leftover:
		p, rest = group_split_prefix(group_stem(n))
		w = group_words(rest)
		kinds[(p, w[-1] if w else rest)].append(n)
	for (p, kind), ns in sorted(kinds.items()):
		if len(ns) >= 3 and kind not in GROUP_GENERIC_KINDS:
			groups.setdefault(p + group_plural(kind), []).extend(sorted(ns))
		else:
			for n in ns:
				groups[n] = [n]

	for n, dest in GROUP_OVERRIDES.items():
		if n not in lines_of or dest not in lines_of:
			continue
		for g, ms in list(groups.items()):
			if n in ms:
				ms.remove(n)
				if not ms:
					del groups[g]
		groups[next(g for g, ms in groups.items() if dest in ms)].append(n)
	return groups


def group_files(pkg):
	"""Merges csgen's one file per class or protocol into one file per family or topic (see `plan_groups`)."""
	RE_CLASS     = re.compile(r'^@\(objc_class="(\w+)"[^\n]*\n(\w+) :: struct *\{(.*?)\}', re.M | re.S)
	RE_ANY_IMPORT = re.compile(r'^import\s+(?:(\w+)\s+)?"([^"]+)"\s*$')
	kept = {}
	parsed = {} # type -> (build tag, package line, imports, body)
	odin_names, raw_super, raw_parents = {}, {}, {}
	for fname, lines in pkg.files.items():
		name = fname[:-len(".odin")]
		if name == pkg.name or name.startswith(pkg.name + "_") or name == "Foundation.Exports":
			kept[fname] = lines
			continue
		k = 0
		tag = package = None
		imports = []
		while k < len(lines):
			line = lines[k]
			if line.startswith("#+build "):
				tag = line[len("#+build "):].strip()
			elif line.startswith("package "):
				package = line
			elif RE_ANY_IMPORT.match(line):
				imports.append(line)
			elif line.strip():
				break
			k += 1
		if tag is None or package is None:
			kept[fname] = lines
			pkg.report["files not grouped (unexpected header)"].append(fname)
			continue
		body = lines[k:]
		while body and not body[-1].strip():
			body.pop()
		parsed[name] = (tag, package, imports, body)

		m = RE_CLASS.search("\n".join(body))
		if m:
			odin_names[m.group(2)] = m.group(1)
			raw_parents[name] = set(re.findall(r"using _: (\w+)\s*[,}\n]", m.group(3) + "\n"))
			s = re.search(r"objc_superclass=(\w+)\)", m.group(0))
			if s:
				raw_super[name] = s.group(1)
				raw_parents[name].add(s.group(1))

	# as written out: marker, build tag, package, blank, imports and blank, body
	lines_of   = {n: 4 + (len(p[2]) + 1 if p[2] else 0) + len(p[3]) for n, p in parsed.items()}
	super_of   = {n: odin_names[p] for n, p in raw_super.items() if p in odin_names}
	parents_of = {n: {odin_names[p] for p in ps if p in odin_names} for n, ps in raw_parents.items()}
	groups = plan_groups(lines_of, super_of, parents_of)

	tags_in_pkg = {p[0] for p in parsed.values()}
	files = dict(kept)
	for gname, members in sorted(groups.items()):
		by_tag = defaultdict(list)
		for n in members:
			by_tag[parsed[n][0]].append(n)
		for tag, ns in sorted(by_tag.items()):
			suffix = GROUP_PLATFORM_SUFFIXES[tag] if len(tags_in_pkg) > 1 and tag != "darwin" else ""
			fname = f"{gname}{suffix}.odin"
			if fname in files:
				raise SystemExit(f"{pkg.name}: grouped file {fname} would replace another file")
			imports, aliases = [], {}
			for n in ns:
				for imp in parsed[n][2]:
					alias, path = RE_ANY_IMPORT.match(imp).groups()
					alias = alias or re.split(r"[:/]", path)[-1]
					if alias not in aliases:
						aliases[alias] = path
						imports.append(imp)
					elif aliases[alias] != path:
						raise SystemExit(f"{pkg.name}: {fname}: import name {alias} is used for both {aliases[alias]} and {path}")
			out = [f"#+build {tag}", parsed[ns[0]][1], ""]
			if imports:
				out += imports + [""]
			for i, n in enumerate(ns):
				if i:
					out += ["", ""]
				out += parsed[n][3]
			out.append("")
			files[fname] = out
	pkg.report["files grouped"].append(f"{len(parsed)} -> {len(files) - len(kept)}")
	pkg.files = files


def guard_conditional_imports(pkg):
	"""Imports only used inside `when` blocks are unused on other platforms, which `-vet` rejects."""
	for fname, lines in pkg.files.items():
		in_when = []
		when_stack = []
		depth = 0
		for line in lines:
			in_when.append(bool(when_stack))
			if RE_WHEN.match(line):
				when_stack.append(depth)
				depth += 1
			else:
				depth += brace_delta(line)
				while when_stack and when_stack[-1] >= depth:
					when_stack.pop()

		imports = [(k, RE_IMPORT.match(l).group(1)) for k, l in enumerate(lines) if RE_IMPORT.match(l)]
		guards = []
		unused = []
		for k, alias in imports:
			uses = re.compile(rf"(?<![\w.]){re.escape(alias)}\.")
			inside = outside = 0
			for j, line in enumerate(lines):
				if j == k or not uses.search(line):
					continue
				if in_when[j]:
					inside += 1
				else:
					outside += 1
			if outside == 0 and inside > 0:
				guards.append(alias)
			elif outside == 0:
				unused.append(k)

		for k in reversed(unused):
			pkg.report["unused imports removed"].append(f"{fname}: {lines[k].strip()}")
			del lines[k]
		if guards:
			last = max(k for k, l in enumerate(lines) if RE_IMPORT.match(l))
			lines[last+1:last+1] = [""] + [f"_ :: {a}" for a in guards]
			pkg.report["platform-only imports guarded"].extend(f"{fname}: {a}" for a in guards)


def apply_known_fixes(pkg):
	for framework, group_name, member in KNOWN_FIXES:
		if framework != pkg.name or member is None:
			continue
		g = next((g for g in pkg.groups if g.name == group_name), None)
		if g is None or member not in g.members:
			pkg.report["known fix no longer applies"].append(f"{group_name}: {member}")
			continue
		lines = pkg.files[g.file]
		k = next(k for k in range(g.decl_idx+1, g.end_idx) if RE_GROUP_MEMBER.match(lines[k]) and RE_GROUP_MEMBER.match(lines[k]).group(2) == member)
		del lines[k]
		pkg.scan()
		pkg.report["known fixes applied"].append(f"{group_name}: -{member}")


def read_lines(path):
	with open(path, encoding="utf-8") as f:
		return f.read().splitlines()


def is_generated(path):
	try:
		with open(path, encoding="utf-8") as f:
			return f.readline().rstrip("\r\n") == GENERATED_MARKER
	except OSError:
		return False


def main():
	ap = argparse.ArgumentParser(description=__doc__.split("\n\n")[0])
	ap.add_argument("darwinkit", help="path to darwodin's darwinkit directory")
	ap.add_argument("--dry-run", action="store_true", help="report what would change without writing")
	ap.add_argument("--verbose", "-v", action="store_true", help="list every reported item")
	args = ap.parse_args()

	odin_root = os.path.normpath(os.path.join(os.path.dirname(os.path.abspath(__file__)), "..", "..", ".."))
	src_root = os.path.abspath(args.darwinkit)

	frameworks = sorted(d for d in os.listdir(src_root) if os.path.isdir(os.path.join(src_root, d)) and d not in SKIPPED_FRAMEWORKS)
	framework_of_path = {}
	dest_of = {}
	for fw in frameworks:
		if fw in CORE_FRAMEWORKS:
			framework_of_path[fw] = f"core:sys/darwin/{fw}"
			dest_of[fw] = os.path.join(odin_root, "core", "sys", "darwin", fw)
		else:
			framework_of_path[fw] = f"vendor:darwin/{fw}"
			dest_of[fw] = os.path.join(odin_root, "vendor", "darwin", fw)

	total_wrappers = 0
	conflicts = []
	for fw in frameworks:
		src = os.path.join(src_root, fw)
		files = {f: read_lines(os.path.join(src, f)) for f in sorted(os.listdir(src)) if f.endswith(".odin")}
		pkg = Package(fw, files)

		rewrite_imports(pkg, framework_of_path)
		apply_alias_fixes(pkg)
		unflag_enums(pkg)
		apply_enum_member_fixes(pkg)
		strip_c_member_prefixes(pkg)
		apply_flag_enums(pkg)
		pkg.scan()
		apply_known_fixes(pkg)
		pkg.scan() # known fixes may remove lines
		plan_error_wrappers(pkg)
		apply_error_wrappers(pkg)
		fix_class_method_groups(pkg)
		apply_extra_overloads(pkg, find_handwritten_procs(dest_of[fw]))
		group_files(pkg)               # replaces pkg.files
		guard_conditional_imports(pkg) # shifts lines
		if "Foundation" in dest_of:
			reexport_foundation_extras(pkg, dest_of["Foundation"])
		total_wrappers += len(pkg.wrappers)

		dest = dest_of[fw]
		rel = os.path.relpath(dest, odin_root).replace(os.sep, "/")
		summary = f"{rel}: {len(pkg.files)} files, {len(pkg.wrappers)} error wrappers"
		for k, v in pkg.report.items():
			summary += f", {k}: {len(v)}"
		print(summary)
		if args.verbose:
			for k, v in pkg.report.items():
				for item in v:
					print(f"\t{k}: {item}")

		if os.path.isdir(dest):
			for f in os.listdir(dest):
				p = os.path.join(dest, f)
				if f in pkg.files and not is_generated(p):
					conflicts.append(p)
		if args.dry_run:
			continue
		if any(c.startswith(dest + os.sep) for c in conflicts):
			continue

		os.makedirs(dest, exist_ok=True)
		for f in os.listdir(dest):
			p = os.path.join(dest, f)
			if f.endswith(".odin") and f not in pkg.files and is_generated(p):
				os.remove(p)
		for f, lines in pkg.files.items():
			with open(os.path.join(dest, f), "w", encoding="utf-8", newline="\n") as out:
				out.write(GENERATED_MARKER + "\n")
				out.write("\n".join(lines).rstrip("\n") + "\n")

	print(f"\n{len(frameworks)} frameworks, {total_wrappers} error wrappers")
	if conflicts:
		print("\nRefusing to overwrite hand-written files (remove or rename them first):", file=sys.stderr)
		for c in conflicts:
			print(f"\t{os.path.relpath(c, odin_root)}", file=sys.stderr)
		sys.exit(1)


if __name__ == "__main__":
	main()
